import numpy as np
G=np.zeros((30,30),dtype=int)
for r,line in enumerate(rows):
    if not line.strip(): continue
    for part in line.split(';'):
        for tok in part.split(): G[r,int(tok)]=1
print('row count',len(rows),'ones',int(G.sum()))
# connected component ids for ones 4-neighbor
from collections import deque, defaultdict
nbr=[(-1,0),(1,0),(0,-1),(0,1)]
def comps(mask):
    ids=np.full(mask.shape,-1,int); sizes=[];
    for r,c in zip(*np.where(mask)):
        if ids[r,c]>=0: continue
        k=len(sizes); q=[(r,c)]; ids[r,c]=k; sz=0
        for y,x in q:
            sz+=1
            for dy,dx in nbr:
                yy,xx=y+dy,x+dx
                if 0<=yy<30 and 0<=xx<30 and mask[yy,xx] and ids[yy,xx]<0:
                    ids[yy,xx]=k;q.append((yy,xx))
        sizes.append(sz)
    return ids,sizes
id1,sizes1=comps(G==1)
id0,sizes0=comps(G==0)
# zero comps touching border, and their adjacent 1 component ids
border0=set()
for r in range(30):
 for c in range(30):
  if G[r,c]==0 and (r==0 or r==29 or c==0 or c==29): border0.add(id0[r,c])
print('1 comp sizes',sizes1)
print('zero comps',[(i,s, i in border0) for i,s in enumerate(sizes0)])
for zi,sz in enumerate(sizes0):
    adj=set()
    for r,c in zip(*np.where(id0==zi)):
        for dy,dx in nbr:
            y,x=r+dy,c+dx
            if 0<=y<30 and 0<=x<30 and G[y,x]==1: adj.add(id1[y,x])
    if zi not in border0 or adj:
       print('zero',zi,'size',sz,'outside',zi in border0,'adj1',adj,'bbox', (np.where(id0==zi)[0].min(),np.where(id0==zi)[0].max(),np.where(id0==zi)[1].min(),np.where(id0==zi)[1].max()))

# identify components bounding boxes
for k in range(len(sizes1)):
    rr,cc=np.where(id1==k)
    print(k, sizes1[k], (rr.min(),rr.max(),cc.min(),cc.max()))
# eligible components from enclosed zero regions
eligible=set()
for zi,sz in enumerate(sizes0):
    if zi in border0: continue
    for r,c in zip(*np.where(id0==zi)):
        for dy,dx in nbr:
            y,x=r+dy,c+dx
            if 0<=y<30 and 0<=x<30 and G[y,x]==1: eligible.add(id1[y,x])
print('eligible',eligible)
O=G.copy()
for r in range(30):
 for c in range(30):
    if G[r,c]!=0: continue
    touching=[id1[r+dy,c+dx] for dy,dx in nbr if 0<=r+dy<30 and 0<=c+dx<30 and G[r+dy,c+dx]==1]
